'use strict';

// MODULES //

var tape = require( 'tape' );
var Complex64 = require( '@stdlib/complex/float32/ctor' );
var Complex128 = require( '@stdlib/complex/float64/ctor' );
var defaults = require( '@stdlib/ndarray/defaults' );
var scalarDataType = require( './../lib' );


// VARIABLES //

var DEFAULT_REAL = defaults.get( 'dtypes.real_floating_point' );
var DEFAULT_CMPLX = defaults.get( 'dtypes.complex_floating_point' );
var DEFAULT_BOOL = defaults.get( 'dtypes.boolean' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof scalarDataType, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns the default real-valued floating-point data type for a number', function test( t ) {
	var values;
	var i;

	values = [
		0.0,
		3.0,
		-3.0,
		3.14,
		NaN,
		1.0/0.0,
		-1.0/0.0
	];
	for ( i = 0; i < values.length; i++ ) {
		t.strictEqual( scalarDataType( values[ i ] ), DEFAULT_REAL, 'returns expected value when provided '+values[ i ] );
	}
	t.end();
});

tape( 'the function returns the default boolean data type for a boolean', function test( t ) {
	t.strictEqual( scalarDataType( true ), DEFAULT_BOOL, 'returns expected value when provided true' );
	t.strictEqual( scalarDataType( false ), DEFAULT_BOOL, 'returns expected value when provided false' );
	t.end();
});

tape( 'the function returns a corresponding complex number data type for a complex number', function test( t ) {
	t.strictEqual( scalarDataType( new Complex128( 1.0, 2.0 ) ), 'complex128', 'returns expected value when provided a Complex128' );
	t.strictEqual( scalarDataType( new Complex64( 1.0, 2.0 ) ), 'complex64', 'returns expected value when provided a Complex64' );
	t.end();
});

tape( 'the function returns the default complex-valued floating-point data type for a complex-like object having an unrecognized data type', function test( t ) {
	var v = {
		're': 1.0,
		'im': 2.0
	};
	t.strictEqual( scalarDataType( v ), DEFAULT_CMPLX, 'returns expected value' );
	t.end();
});

tape( 'the function returns "generic" for all other values', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		'beep',
		null,
		void 0,
		[],
		{},
		function noop() {},
		new Number( 3.0 ), // eslint-disable-line no-new-wrappers
		new Boolean( true ) // eslint-disable-line no-new-wrappers
	];
	for ( i = 0; i < values.length; i++ ) {
		t.strictEqual( scalarDataType( values[ i ] ), 'generic', 'returns expected value when provided '+String( values[ i ] ) );
	}
	t.end();
});
